#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(RES2_CTX_IN.len(), 32);
    assert_eq!(RES2_CTX_OUT.len(), RES2_CTX_IN.len());
    assert_eq!(RES2_FRAMES_IN.len(), 12);
    assert_eq!(RES2_FRAMES_OUT.len(), RES2_FRAMES_IN.len());
    assert!(RES2_FRAMES_IN != RES2_FRAMES_OUT);
    assert_eq!(RES4_CTX_IN.len(), 32);
    assert_eq!(RES4_CTX_OUT.len(), RES4_CTX_IN.len());
    assert_eq!(RES4_FRAMES_IN.len(), 24);
    assert_eq!(RES4_FRAMES_OUT.len(), RES4_FRAMES_IN.len());
    assert!(RES4_FRAMES_IN != RES4_FRAMES_OUT);
}
